-- Operations case and knowledge schema. Generated by go run ./cmd/ops-schema.
CREATE TABLE IF NOT EXISTS `ops_case` (`id` bigint AUTO_INCREMENT,`group_id` bigint NOT NULL,`severity` bigint,`title` varchar(255) NOT NULL,`state` varchar(24) NOT NULL,`wait_reason` varchar(64) NOT NULL DEFAULT '',`owner_id` bigint NOT NULL DEFAULT 0,`target_ident` varchar(255) NOT NULL DEFAULT '',`datasource_id` bigint NOT NULL DEFAULT 0,`rule_id` bigint NOT NULL DEFAULT 0,`context` LONGTEXT,`knowledge_version_id` bigint NOT NULL DEFAULT 0,`plan_id` bigint NOT NULL DEFAULT 0,`revision` bigint NOT NULL DEFAULT 1,`generation` bigint NOT NULL DEFAULT 1,`close_type` varchar(40) NOT NULL DEFAULT '',`summary` text,`followup` text,`created_by` bigint,`created_at` bigint,`updated_at` bigint,`closed_at` bigint,PRIMARY KEY (`id`),INDEX `idx_ops_case_group_state` (`group_id`,`state`),INDEX `idx_ops_case_owner_id` (`owner_id`),INDEX `idx_ops_case_created_at` (`created_at`));
CREATE TABLE IF NOT EXISTS `ops_episode` (`id` bigint AUTO_INCREMENT,`case_id` bigint NOT NULL,`group_id` bigint NOT NULL,`incident_id` varchar(64) NOT NULL,`sequence` bigint,`recovered` boolean,`snapshot` LONGTEXT,`updated_at` bigint,PRIMARY KEY (`id`),INDEX `idx_ops_episode_group_id` (`group_id`),INDEX `idx_ops_episode_case_id` (`case_id`),CONSTRAINT `uni_ops_episode_incident_id` UNIQUE (`incident_id`));
CREATE TABLE IF NOT EXISTS `ops_inbox` (`id` bigint AUTO_INCREMENT,`dispatch_id` varchar(64) NOT NULL,`incident_id` varchar(64) NOT NULL,`case_id` bigint NOT NULL,`created_at` bigint,PRIMARY KEY (`id`),INDEX `idx_ops_inbox_incident_id` (`incident_id`),INDEX `idx_ops_inbox_case_id` (`case_id`),CONSTRAINT `uni_ops_inbox_dispatch_id` UNIQUE (`dispatch_id`));
CREATE TABLE IF NOT EXISTS `ops_evidence` (`id` bigint AUTO_INCREMENT,`case_id` bigint NOT NULL,`generation` bigint,`kind` varchar(40) NOT NULL,`source` varchar(255) NOT NULL,`status` varchar(24) NOT NULL,`observed_at` bigint,`window_start` bigint,`window_end` bigint,`collected_at` bigint,`payload` LONGTEXT,`sha256` varchar(64) NOT NULL,`created_by` bigint,PRIMARY KEY (`id`),INDEX `idx_ops_evidence_case_id` (`case_id`));
CREATE TABLE IF NOT EXISTS `ops_step` (`plan_id` bigint NOT NULL DEFAULT 0,`id` bigint AUTO_INCREMENT,`case_id` bigint NOT NULL,`generation` bigint,`version_id` bigint,`step_key` varchar(64) NOT NULL,`state` varchar(24) NOT NULL,`evidence_ids` LONGTEXT,`note` text,`created_by` bigint,`created_at` bigint,PRIMARY KEY (`id`),INDEX `idx_ops_step_case_id` (`case_id`));
CREATE TABLE IF NOT EXISTS `ops_audit` (`id` bigint AUTO_INCREMENT,`case_id` bigint NOT NULL,`actor_id` bigint,`action` varchar(64) NOT NULL,`detail` LONGTEXT,`created_at` bigint,PRIMARY KEY (`id`),INDEX `idx_ops_audit_case_id` (`case_id`));
CREATE TABLE IF NOT EXISTS `ops_action` (`plan_id` bigint NOT NULL DEFAULT 0,`id` bigint AUTO_INCREMENT,`case_id` bigint NOT NULL,`generation` bigint,`version_id` bigint,`kind` varchar(32) NOT NULL,`state` varchar(24) NOT NULL,`operation_key` varchar(64) NOT NULL,`baseline` varchar(64) NOT NULL,`payload` LONGTEXT,`result` LONGTEXT,`proposed_by` bigint,`approved_by` bigint,`expires_at` bigint,`created_at` bigint,`updated_at` bigint,PRIMARY KEY (`id`),INDEX `idx_ops_action_case_id` (`case_id`),INDEX `idx_ops_action_state` (`state`),CONSTRAINT `uni_ops_action_operation_key` UNIQUE (`operation_key`));
CREATE TABLE IF NOT EXISTS `ops_verification` (`plan_id` bigint NOT NULL DEFAULT 0,`id` bigint AUTO_INCREMENT,`case_id` bigint NOT NULL,`generation` bigint,`version_id` bigint,`check_key` varchar(64) NOT NULL,`state` varchar(24) NOT NULL,`reason` text,`evidence_ids` LONGTEXT,`confirmed_by` bigint,`created_at` bigint,PRIMARY KEY (`id`),INDEX `idx_ops_verification_case_id` (`case_id`));
CREATE TABLE IF NOT EXISTS `ops_run` (`id` bigint AUTO_INCREMENT,`case_id` bigint NOT NULL,`active_case_id` bigint,`user_id` bigint,`state` varchar(24) NOT NULL,`fence` bigint NOT NULL DEFAULT 0,`lease_until` bigint,`next_run_at` bigint,`attempts` bigint,`mode` varchar(24) NOT NULL,`result` text,`created_at` bigint,`updated_at` bigint,PRIMARY KEY (`id`),INDEX `idx_ops_run_case_id` (`case_id`),INDEX `idx_ops_run_state` (`state`),CONSTRAINT `uni_ops_run_active_case_id` UNIQUE (`active_case_id`));
CREATE TABLE IF NOT EXISTS `ops_policy` (`id` bigint AUTO_INCREMENT,`group_id` bigint NOT NULL,`enabled` boolean,`service_user_id` bigint,`auto_investigate` boolean,`rule_ids` LONGTEXT,`revision` bigint NOT NULL DEFAULT 1,`scan_at` bigint,`scan_id` bigint,`reconcile_at` bigint,`health` varchar(255),`gap_since` bigint,PRIMARY KEY (`id`),CONSTRAINT `uni_ops_policy_group_id` UNIQUE (`group_id`));
CREATE TABLE IF NOT EXISTS `ops_plan` (`id` bigint AUTO_INCREMENT,`case_id` bigint NOT NULL,`sequence` bigint NOT NULL,`title` varchar(255) NOT NULL,`scope` text,`rationale` text,`payload` LONGTEXT,`evidence_ids` LONGTEXT,`sha256` varchar(64) NOT NULL,`generation` bigint,`evidence_anchor` bigint,`confirmed_generation` bigint,`state` varchar(24) NOT NULL,`created_by` bigint,`created_at` bigint,`confirmed_by` bigint,`confirmed_at` bigint,`decision_note` text,PRIMARY KEY (`id`),UNIQUE INDEX `idx_ops_plan_case_sequence` (`case_id`,`sequence`));
CREATE TABLE IF NOT EXISTS `ops_knowledge` (`id` bigint AUTO_INCREMENT,`group_id` bigint NOT NULL,`title` varchar(255) NOT NULL,`draft` LONGTEXT,`revision` bigint NOT NULL DEFAULT 1,`current_version_id` bigint NOT NULL DEFAULT 0,`created_by` bigint,`updated_by` bigint,`updated_at` bigint,PRIMARY KEY (`id`),INDEX `idx_ops_knowledge_group_id` (`group_id`));
CREATE TABLE IF NOT EXISTS `ops_knowledge_version` (`id` bigint AUTO_INCREMENT,`item_id` bigint NOT NULL,`group_id` bigint NOT NULL,`sequence` bigint NOT NULL,`title` varchar(255) NOT NULL,`payload` LONGTEXT,`sha256` varchar(64) NOT NULL,`published_by` bigint,`published_at` bigint,`withdrawn_at` bigint,`withdraw_reason` text,PRIMARY KEY (`id`),UNIQUE INDEX `idx_ops_knowledge_sequence` (`item_id`,`sequence`),INDEX `idx_ops_knowledge_version_group_id` (`group_id`));
CREATE TABLE IF NOT EXISTS `ops_knowledge_source` (`id` bigint AUTO_INCREMENT,`group_id` bigint NOT NULL,`name` varchar(255) NOT NULL,`media_type` varchar(120) NOT NULL,`storage_key` varchar(64) NOT NULL,`sha256` varchar(64) NOT NULL,`size` bigint,`description` text,`created_by` bigint,`created_at` bigint,PRIMARY KEY (`id`),INDEX `idx_ops_knowledge_source_group_id` (`group_id`),CONSTRAINT `uni_ops_knowledge_source_storage_key` UNIQUE (`storage_key`));
